def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]
    prev_my = history[-2][0]
    prev_opp = history[-2][1]

    opp_d_total = 0
    my_d_total = 0
    for m, o in history:
        if m == 'D':
            my_d_total += 1
        if o == 'D':
            opp_d_total += 1

    start = n - 10
    if start < 0:
        start = 0
    opp_d_recent = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            opp_d_recent += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    no_punish = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D' and history[i - 1][1] == 'C':
            if history[i][1] == 'D':
                punish += 1
            elif history[i][1] == 'C':
                no_punish += 1

    if (no_punish + punish == 0 and my_d_total == 0 and
            opp_d_total <= 2 and opp_last == 'C' and
            n in (10, 14, 18, 22, 26, 30)):
        return 'D'

    if n < 15:
        hostile = opp_d_total >= 6 or (opp_d_total >= 4 and n >= 10 and opp_d_recent >= 4)
    else:
        hostile = opp_d_total * 2 > n or opp_d_recent >= 7

    if hostile:
        if opp_last == 'C' and my_last == 'D' and my_d_streak >= 2:
            if opp_d_total * 10 < n * 7 and rng.random() < 0.25:
                return 'C'
        if opp_d_streak == 0 and my_d_streak >= 3:
            if opp_d_total * 10 < n * 7 and rng.random() < 0.15:
                return 'C'
        return 'D'

    exploit_p = 0.0
    if punish == 0:
        if no_punish >= 8:
            exploit_p = 0.90
        elif no_punish >= 6:
            exploit_p = 0.75
        elif no_punish >= 4:
            exploit_p = 0.55
        elif no_punish >= 2:
            exploit_p = 0.35
        elif no_punish == 1:
            exploit_p = 0.20
    elif no_punish > punish * 2:
        exploit_p = 0.12
    elif no_punish > punish:
        exploit_p = 0.05

    if opp_d_total * 5 > n:
        exploit_p *= 0.5
    if opp_d_total * 10 > n * 3:
        exploit_p *= 0.3
    if opp_d_recent >= 4:
        exploit_p *= 0.4
    if exploit_p > 0.90:
        exploit_p = 0.90

    if n >= 96:
        if punish == 0 and opp_d_total <= 2:
            return 'D'
        if opp_last == 'D' or my_last == 'D' or exploit_p > 0.40:
            return 'D'
    if n >= 98:
        if punish == 0:
            return 'D'
        if opp_last == 'D' or my_last == 'D' or exploit_p > 0.25:
            return 'D'

    if opp_last == 'D':
        if opp_d_streak >= 3:
            return 'D'
        if my_last == 'D':
            if opp_d_recent <= 2:
                return 'C' if rng.random() < 0.70 else 'D'
            return 'C' if rng.random() < 0.45 else 'D'
        if prev_my == 'D' and prev_opp == 'C':
            return 'C'
        if opp_d_streak == 1 and opp_d_total <= 3 and n < 80:
            return 'D' if rng.random() < 0.75 else 'C'
        if opp_d_streak == 1 and opp_d_total <= 5 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if my_last == 'D':
        if exploit_p >= 0.55:
            if punish == 0 and opp_d_total == 0 and no_punish >= 8:
                max_streak = 5
                p = 0.95
            else:
                max_streak = 2
                p = 0.80
            if my_d_streak < max_streak:
                return 'D' if rng.random() < p else 'C'
        if exploit_p >= 0.35 and my_d_streak == 1 and punish == 0:
            return 'D' if rng.random() < exploit_p else 'C'
        return 'C'

    if exploit_p > 0.0:
        if rng.random() < exploit_p:
            return 'D'
    return 'C'
